// Shared configuration and helpers for the POPIA edge functions.
// Deno (Supabase Edge Runtime). Engineering guidance, not legal advice.
//
// Edit PRIVACY_TABLES to describe where each user's personal information lives.
// Keep it in step with privacy.data_inventory (s17).

import { createClient, type SupabaseClient, type User } from "npm:@supabase/supabase-js@2.45.4";

export type DeletionStrategy =
  /** Delete matching rows. */
  | { mode: "delete" }
  /** Null or overwrite the listed columns and keep the row (s14(4) de-identify). */
  | { mode: "deidentify"; columns: Record<string, null | string>; markColumn?: string }
  /** Keep the row because a law requires it, but strip non-required columns (s14(6) restrict). */
  | { mode: "retain"; reason: string; columns?: Record<string, null | string> };

export interface PrivacyTable {
  /** Schema name, usually "public". */
  schema: string;
  table: string;
  /** Column that holds the auth user id. */
  userColumn: string;
  /** Columns to include in a "download my data" export (s23). Use ["*"] for all. */
  exportColumns: string[];
  /** What dsar-delete does with this table (s24, s14). */
  onDelete: DeletionStrategy;
}

/**
 * EXAMPLE CONFIG. Replace with your own tables before deploying.
 * Order matters for deletion: children before parents if you have foreign keys.
 */
export const PRIVACY_TABLES: PrivacyTable[] = [
  {
    schema: "public",
    table: "profiles",
    userColumn: "id",
    exportColumns: ["*"],
    onDelete: {
      mode: "deidentify",
      columns: { full_name: null, email: null, phone: null, avatar_url: null },
      markColumn: "deidentified_at",
    },
  },
  {
    schema: "public",
    table: "orders",
    userColumn: "user_id",
    exportColumns: ["id", "created_at", "total", "status"],
    // Tax records: commonly kept 5 years (Tax Administration Act). VERIFY for your sector.
    onDelete: {
      mode: "retain",
      reason: "Tax record retention",
      columns: { shipping_address: null, phone: null, notes: null },
    },
  },
  {
    schema: "public",
    table: "support_messages",
    userColumn: "user_id",
    exportColumns: ["*"],
    onDelete: { mode: "delete" },
  },
];

/** Storage buckets whose objects live under a "<user_id>/" prefix. */
export const PRIVACY_BUCKETS: string[] = [
  // "avatars",
  // "documents",
];

/** Delete the auth user after de-identifying their data. */
export const DELETE_AUTH_USER = true;

// ---------------------------------------------------------------------------
// Environment
// ---------------------------------------------------------------------------

export function env(name: string, required = true): string {
  const v = Deno.env.get(name) ?? "";
  if (required && !v) throw new Error(`Missing environment variable ${name}`);
  return v;
}

/** Service-role client. Server only. Never expose this key to the browser (s19). */
export function adminClient(): SupabaseClient {
  return createClient(env("SUPABASE_URL"), env("SUPABASE_SERVICE_ROLE_KEY"), {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

// ---------------------------------------------------------------------------
// Identity: always from the JWT, never from the request body
// ---------------------------------------------------------------------------

export async function requireUser(req: Request, admin: SupabaseClient): Promise<User> {
  const header = req.headers.get("Authorization") ?? "";
  const jwt = header.startsWith("Bearer ") ? header.slice(7) : "";
  if (!jwt) throw new HttpError(401, "Sign in to continue.");
  const { data, error } = await admin.auth.getUser(jwt);
  if (error || !data?.user) throw new HttpError(401, "Your session has expired. Sign in again.");
  return data.user;
}

/**
 * Destructive actions (account deletion) need a recent sign-in, so a stolen or
 * long-lived session cannot erase an account on its own. Window in minutes from
 * RECENT_AUTH_MINUTES (default 15). Your app should ask the person to sign in
 * again (password, magic link or OTP) and then retry.
 */
export function requireRecentSignIn(user: User): void {
  const minutes = Number(Deno.env.get("RECENT_AUTH_MINUTES") ?? "15");
  const last = user.last_sign_in_at ? Date.parse(user.last_sign_in_at) : NaN;
  if (!Number.isFinite(last) || Date.now() - last > minutes * 60_000) {
    throw new HttpError(401, "For your security, sign in again to confirm this request.");
  }
}

/** Simple per-user rate limit backed by privacy.dsar_requests. */
export async function rateLimitRequests(
  admin: SupabaseClient,
  userId: string,
  type: string,
  maxPerHour: number,
): Promise<void> {
  const since = new Date(Date.now() - 3_600_000).toISOString();
  const { count, error } = await admin
    .schema("privacy")
    .from("dsar_requests")
    .select("id", { count: "exact", head: true })
    .eq("subject_id", userId)
    .eq("type", type)
    .gte("received_at", since);
  if (error) throw new Error("rate_limit_check_failed");
  if ((count ?? 0) >= maxPerHour) throw new HttpError(429, "Too many requests. Try again in an hour.");
}

// ---------------------------------------------------------------------------
// Storage: list every object under a prefix (all pages, all sub-folders)
// ---------------------------------------------------------------------------

const STORAGE_PAGE = 100;
const STORAGE_MAX_OBJECTS = 10_000;

/**
 * Returns every object path under `prefix` in `bucket`. Throws on any listing
 * error, so callers never mistake a failed listing for an empty folder.
 * Supabase lists one level at a time; folders come back with a null id.
 */
export async function listAllObjects(admin: SupabaseClient, bucket: string, prefix: string): Promise<string[]> {
  const out: string[] = [];
  const folders = [prefix.replace(/\/+$/, "")];
  while (folders.length > 0) {
    const folder = folders.pop() as string;
    for (let offset = 0; ; offset += STORAGE_PAGE) {
      const { data, error } = await admin.storage.from(bucket).list(folder, { limit: STORAGE_PAGE, offset });
      if (error) throw new Error("storage_list_failed");
      const items = data ?? [];
      for (const item of items) {
        const path = `${folder}/${item.name}`;
        if (item.id === null) folders.push(path);
        else out.push(path);
        if (out.length > STORAGE_MAX_OBJECTS) throw new Error("storage_too_many_objects");
      }
      if (items.length < STORAGE_PAGE) break;
    }
  }
  return out;
}

/** Removes paths in batches. Throws if any batch fails. */
export async function removeObjects(admin: SupabaseClient, bucket: string, paths: string[]): Promise<void> {
  for (let i = 0; i < paths.length; i += STORAGE_PAGE) {
    const { error } = await admin.storage.from(bucket).remove(paths.slice(i, i + STORAGE_PAGE));
    if (error) throw new Error("storage_remove_failed");
  }
}

// ---------------------------------------------------------------------------
// CORS allow-list from ALLOWED_ORIGINS (comma-separated)
// ---------------------------------------------------------------------------

function allowedOrigins(): string[] {
  return (Deno.env.get("ALLOWED_ORIGINS") ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

export function corsHeaders(req: Request, methods = "POST, OPTIONS"): Record<string, string> {
  const origin = req.headers.get("Origin") ?? "";
  const headers: Record<string, string> = {
    "Access-Control-Allow-Methods": methods,
    "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
    "Access-Control-Max-Age": "600",
    Vary: "Origin",
  };
  if (origin && allowedOrigins().includes(origin)) {
    headers["Access-Control-Allow-Origin"] = origin;
  }
  return headers;
}

/** Reject browser requests from origins not on the allow-list. Server-to-server calls have no Origin. */
export function assertOrigin(req: Request): void {
  const origin = req.headers.get("Origin");
  if (origin && !allowedOrigins().includes(origin)) {
    throw new HttpError(403, "Origin not allowed.");
  }
}

// ---------------------------------------------------------------------------
// Responses and errors
// ---------------------------------------------------------------------------

export class HttpError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

export function json(req: Request, body: unknown, status = 200, methods?: string): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders(req, methods),
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}

/** Map an error to a response without leaking internals or personal information. */
export function errorResponse(req: Request, err: unknown, methods?: string): Response {
  if (err instanceof HttpError) return json(req, { error: err.message }, err.status, methods);
  // Log the error type only. Never log request bodies, emails or tokens (s19).
  console.error("privacy function error", err instanceof Error ? err.name : typeof err);
  return json(req, { error: "Something went wrong. Try again later." }, 500, methods);
}

// ---------------------------------------------------------------------------
// Crypto helpers
// ---------------------------------------------------------------------------

const enc = new TextEncoder();

export function toHex(buf: ArrayBuffer): string {
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export async function sha256Hex(input: string): Promise<string> {
  return toHex(await crypto.subtle.digest("SHA-256", enc.encode(input)));
}

export async function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}

export function base64UrlEncode(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function base64UrlDecode(input: string): Uint8Array {
  const pad = input.length % 4 === 0 ? "" : "=".repeat(4 - (input.length % 4));
  const b64 = input.replace(/-/g, "+").replace(/_/g, "/") + pad;
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ---------------------------------------------------------------------------
// Unsubscribe tokens (s69(4), s11(3)(b))
// ---------------------------------------------------------------------------
// Format: base64url(JSON payload) + "." + base64url(HMAC-SHA256(payload)).
// No expiry by default: an unsubscribe link must keep working.
// Put only the subject id and purposes in the payload, never an email address.

export interface UnsubscribePayload {
  /** Subject id (auth user id or lead id). */
  s: string;
  /** Purposes to withdraw, for example ["marketing_email"]. Empty means all marketing. */
  p: string[];
  /** Issued at, seconds since epoch. */
  iat: number;
}

export const MARKETING_PURPOSES = ["marketing_email", "marketing_sms", "marketing_whatsapp", "marketing_phone"];

export async function signUnsubscribeToken(payload: Omit<UnsubscribePayload, "iat">, secret: string): Promise<string> {
  const full: UnsubscribePayload = { ...payload, iat: Math.floor(Date.now() / 1000) };
  const body = base64UrlEncode(enc.encode(JSON.stringify(full)));
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(secret), enc.encode(body)));
  return `${body}.${base64UrlEncode(sig)}`;
}

export async function verifyUnsubscribeToken(token: string, secret: string): Promise<UnsubscribePayload | null> {
  const [body, sig] = token.split(".");
  if (!body || !sig) return null;
  try {
    // crypto.subtle.verify compares in constant time.
    const ok = await crypto.subtle.verify("HMAC", await hmacKey(secret), base64UrlDecode(sig) as BufferSource, enc.encode(body));
    if (!ok) return null;
    const parsed = JSON.parse(new TextDecoder().decode(base64UrlDecode(body))) as UnsubscribePayload;
    if (typeof parsed.s !== "string" || !Array.isArray(parsed.p)) return null;
    return parsed;
  } catch {
    return null;
  }
}

/** Client IP from standard proxy headers. Only ever stored hashed. */
export function clientIp(req: Request): string | null {
  const xff = req.headers.get("x-forwarded-for");
  if (xff) return xff.split(",")[0].trim();
  return req.headers.get("x-real-ip") ?? req.headers.get("cf-connecting-ip");
}

// ---------------------------------------------------------------------------
// Audit
// ---------------------------------------------------------------------------

export async function audit(
  admin: SupabaseClient,
  entry: { actor_id: string | null; actor_role: string; action: string; data_store: string; subject_id: string | null; reason?: string; details?: Record<string, unknown> },
): Promise<void> {
  const { error } = await admin.schema("privacy").from("access_audit").insert({ ...entry, details: entry.details ?? {} });
  if (error) console.error("access_audit insert failed", error.code);
}

// dsar-export: "Download my data" (s23(1)(b) right of access).
// Deno edge function. Engineering guidance, not legal advice.
//
// POST with the user's JWT in Authorization. Returns a JSON file of the
// personal information configured in _shared/privacy-config.ts, plus their
// consent history and DSAR requests. Logs the export in privacy.access_audit
// and records a completed 'access' request in privacy.dsar_requests.
//
// Identity comes from the JWT only (s19). A user can only export their own data.

import {
  PRIVACY_BUCKETS,
  PRIVACY_TABLES,
  adminClient,
  assertOrigin,
  audit,
  corsHeaders,
  errorResponse,
  HttpError,
  listAllObjects,
  rateLimitRequests,
  requireUser,
} from "../_shared/privacy-config.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders(req) });
  try {
    if (req.method !== "POST") throw new HttpError(405, "Use POST.");
    assertOrigin(req);
    const admin = adminClient();
    const user = await requireUser(req, admin);
    // Exports are expensive and hold everything about a person: limit them per user.
    await rateLimitRequests(admin, user.id, "access", Number(Deno.env.get("EXPORTS_PER_HOUR") ?? "3"));

    const tables: Record<string, unknown> = {};
    for (const t of PRIVACY_TABLES) {
      const { data, error } = await admin
        .schema(t.schema)
        .from(t.table)
        .select(t.exportColumns.join(","))
        .eq(t.userColumn, user.id);
      tables[`${t.schema}.${t.table}`] = error ? { error: "Could not read this table." } : data;
    }

    const files: Record<string, string[] | { error: string }> = {};
    for (const bucket of PRIVACY_BUCKETS) {
      try {
        files[bucket] = await listAllObjects(admin, bucket, user.id);
      } catch {
        // Say so rather than presenting an incomplete list as complete (s23).
        files[bucket] = { error: "Could not list your files in this store. Contact us for a full copy." };
      }
    }

    const { data: consent } = await admin
      .schema("privacy")
      .from("consent_events")
      .select("purpose, action, notice_version, wording, channel, created_at")
      .eq("subject_id", user.id)
      .order("created_at", { ascending: true });

    const { data: requests } = await admin
      .schema("privacy")
      .from("dsar_requests")
      .select("type, status, received_at, completed_at, outcome")
      .eq("subject_id", user.id);

    const exportDoc = {
      generated_at: new Date().toISOString(),
      account: {
        id: user.id,
        email: user.email ?? null,
        phone: user.phone ?? null,
        created_at: user.created_at,
        last_sign_in_at: user.last_sign_in_at ?? null,
      },
      tables,
      files,
      consent_history: consent ?? [],
      privacy_requests: requests ?? [],
      note:
        "This is the personal information linked to your account in our systems. Ask us if you need details about who we shared it with (s23(1)(b)).",
    };

    await admin.schema("privacy").from("dsar_requests").insert({
      subject_id: user.id,
      type: "access",
      status: "completed",
      channel: "privacy_centre",
      completed_at: new Date().toISOString(),
      outcome: "Self-service export downloaded",
    });
    await audit(admin, {
      actor_id: user.id,
      actor_role: "data_subject",
      action: "export",
      data_store: "dsar-export",
      subject_id: user.id,
      details: { tables: Object.keys(tables).length },
    });

    return new Response(JSON.stringify(exportDoc, null, 2), {
      status: 200,
      headers: {
        ...corsHeaders(req),
        "Content-Type": "application/json; charset=utf-8",
        "Content-Disposition": `attachment; filename="my-data-${exportDoc.generated_at.slice(0, 10)}.json"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    return errorResponse(req, err);
  }
});

// dsar-delete: "Delete my account" (s24 deletion, s14(4) de-identify, s14(6) restrict).
// Deno edge function. Engineering guidance, not legal advice.
//
// POST { "confirm": true } with the user's JWT in Authorization.
//   1. Records a 'deletion' request in privacy.dsar_requests.
//   2. For each table in PRIVACY_TABLES: delete, de-identify, or retain-and-strip.
//   3. Removes files under "<user_id>/" in PRIVACY_BUCKETS.
//   4. Redacts device and network details from consent evidence.
//   5. Deletes the auth user (if DELETE_AUTH_USER).
//   6. Marks the request completed with an outcome the person can be told (s24(3)).
//
// Identity comes from the JWT only, never from the body.
// Backups age out on their own cycle. State that window in your Privacy Notice.

import {
  DELETE_AUTH_USER,
  PRIVACY_BUCKETS,
  PRIVACY_TABLES,
  adminClient,
  assertOrigin,
  audit,
  corsHeaders,
  errorResponse,
  HttpError,
  json,
  listAllObjects,
  removeObjects,
  requireRecentSignIn,
  requireUser,
} from "../_shared/privacy-config.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders(req) });
  try {
    if (req.method !== "POST") throw new HttpError(405, "Use POST.");
    assertOrigin(req);
    const admin = adminClient();
    const user = await requireUser(req, admin);
    // Deletion is irreversible: require a fresh sign-in, not just any valid session.
    requireRecentSignIn(user);

    let body: { confirm?: unknown } = {};
    try {
      body = await req.json();
    } catch {
      // empty body
    }
    if (body.confirm !== true) throw new HttpError(400, "Confirm the deletion to continue.");

    const { data: request, error: reqErr } = await admin
      .schema("privacy")
      .from("dsar_requests")
      .insert({ subject_id: user.id, type: "deletion", status: "in_progress", channel: "privacy_centre" })
      .select("id")
      .single();
    if (reqErr || !request) throw new Error("dsar_request_insert_failed");

    const results: Array<{ store: string; mode: string; ok: boolean; reason?: string }> = [];

    for (const t of PRIVACY_TABLES) {
      const store = `${t.schema}.${t.table}`;
      const q = admin.schema(t.schema).from(t.table);
      let ok = true;
      if (t.onDelete.mode === "delete") {
        const { error } = await q.delete().eq(t.userColumn, user.id);
        ok = !error;
      } else if (t.onDelete.mode === "deidentify") {
        const patch: Record<string, unknown> = { ...t.onDelete.columns };
        if (t.onDelete.markColumn) patch[t.onDelete.markColumn] = new Date().toISOString();
        const { error } = await q.update(patch).eq(t.userColumn, user.id);
        ok = !error;
      } else {
        // retain: keep the legally required record, strip everything else.
        if (t.onDelete.columns && Object.keys(t.onDelete.columns).length > 0) {
          const { error } = await q.update(t.onDelete.columns).eq(t.userColumn, user.id);
          ok = !error;
        }
      }
      results.push({
        store,
        mode: t.onDelete.mode,
        ok,
        reason: t.onDelete.mode === "retain" ? t.onDelete.reason : undefined,
      });
    }

    for (const bucket of PRIVACY_BUCKETS) {
      // Every page and sub-folder. A failed listing is a failure, never "nothing to delete".
      let ok = true;
      try {
        const paths = await listAllObjects(admin, bucket, user.id);
        await removeObjects(admin, bucket, paths);
        ok = (await listAllObjects(admin, bucket, user.id)).length === 0;
      } catch {
        ok = false;
      }
      results.push({ store: `storage:${bucket}`, mode: "delete", ok });
    }

    // Keep the fact of consent and withdrawal, drop device and network details.
    const { error: redactErr } = await admin.schema("privacy").rpc("redact_consent_events", { p_subject: user.id });
    results.push({ store: "privacy.consent_events", mode: "deidentify", ok: !redactErr });

    const failed = results.filter((r) => !r.ok);
    const retained = results.filter((r) => r.mode === "retain").map((r) => `${r.store} (${r.reason})`);

    if (failed.length === 0 && DELETE_AUTH_USER) {
      const { error } = await admin.auth.admin.deleteUser(user.id);
      results.push({ store: "auth.users", mode: "delete", ok: !error });
    }

    const allOk = results.every((r) => r.ok);
    const outcome = allOk
      ? `Account deleted. Retained by law: ${retained.length ? retained.join("; ") : "none"}.`
      : `Partial. Failed: ${results.filter((r) => !r.ok).map((r) => r.store).join(", ")}. Needs manual follow-up.`;

    await admin
      .schema("privacy")
      .from("dsar_requests")
      .update({
        status: allOk ? "completed" : "in_progress",
        completed_at: allOk ? new Date().toISOString() : null,
        outcome,
      })
      .eq("id", request.id);

    await audit(admin, {
      actor_id: user.id,
      actor_role: "data_subject",
      action: "delete",
      data_store: "dsar-delete",
      subject_id: user.id,
      details: { request_id: request.id, results: results.map(({ store, mode, ok }) => ({ store, mode, ok })) },
    });

    if (!allOk) {
      return json(req, { status: "partial", request_id: request.id, message: "We started your deletion. Some steps need a person to finish them. We will confirm by email." }, 202);
    }
    return json(req, { status: "completed", request_id: request.id, retained });
  } catch (err) {
    return errorResponse(req, err);
  }
});

// consent: record and read consent events (s11(2)(a) burden of proof, s69, s11(2)(b) withdrawal).
// Deno edge function. Engineering guidance, not legal advice.
//
// GET   returns the caller's current consent per purpose (from privacy.consent_current).
// POST  { purpose, action: "granted"|"withdrawn", wording, channel, notice_version?, source_url? }
//       or { events: [ ...same shape ] } for several at once.
//
// Identity comes from the JWT only. For visitors who are not signed in, use
// Supabase anonymous sign-ins so they also carry a JWT, then link the
// anonymous user to the real account on sign-up.
//
// The IP address is hashed with CONSENT_IP_SALT before storage. The raw IP is
// never stored or logged (s10 minimality, s19).
// The server computes notice_version from the wording hash when it is not supplied,
// so the record always pins the exact text.

import {
  adminClient,
  assertOrigin,
  clientIp,
  corsHeaders,
  env,
  errorResponse,
  HttpError,
  json,
  requireUser,
  sha256Hex,
} from "../_shared/privacy-config.ts";

const METHODS = "GET, POST, OPTIONS";
const PURPOSE_RE = /^[a-z0-9_]{1,100}$/;
const CHANNEL_RE = /^[a-z0-9_]{1,50}$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

interface IncomingEvent {
  purpose?: unknown;
  action?: unknown;
  wording?: unknown;
  channel?: unknown;
  notice_version?: unknown;
  source_url?: unknown;
  competent_person_id?: unknown;
}

function str(v: unknown, max: number): string | null {
  return typeof v === "string" && v.length > 0 && v.length <= max ? v : null;
}

function cleanUrl(v: unknown): string | null {
  const s = str(v, 2000);
  if (!s) return null;
  try {
    const u = new URL(s);
    // Drop query and fragment: they often carry email addresses or tokens.
    return `${u.origin}${u.pathname}`;
  } catch {
    return null;
  }
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders(req, METHODS) });
  try {
    assertOrigin(req);
    const admin = adminClient();
    const user = await requireUser(req, admin);

    if (req.method === "GET") {
      const { data, error } = await admin
        .schema("privacy")
        .from("consent_current")
        .select("purpose, action, notice_version, channel, created_at")
        .eq("subject_id", user.id);
      if (error) throw new Error("consent_read_failed");
      return json(req, { current: data ?? [] }, 200, METHODS);
    }

    if (req.method !== "POST") throw new HttpError(405, "Use GET or POST.");

    let body: { events?: IncomingEvent[] } & IncomingEvent;
    try {
      body = await req.json();
    } catch {
      throw new HttpError(400, "Send a JSON body.");
    }
    const incoming: IncomingEvent[] = Array.isArray(body.events) ? body.events : [body];
    if (incoming.length === 0 || incoming.length > 20) throw new HttpError(400, "Send between 1 and 20 events.");

    const salt = env("CONSENT_IP_SALT");
    const ip = clientIp(req);
    const ipHash = ip ? await sha256Hex(`${salt}:${ip}`) : null;
    const ua = req.headers.get("User-Agent")?.slice(0, 500) ?? null;

    const rows = [];
    for (const e of incoming) {
      const purpose = str(e.purpose, 100);
      const channel = str(e.channel, 50) ?? "web_form";
      const wording = str(e.wording, 5000);
      if (!purpose || !PURPOSE_RE.test(purpose)) throw new HttpError(400, "Invalid purpose.");
      if (!CHANNEL_RE.test(channel)) throw new HttpError(400, "Invalid channel.");
      if (e.action !== "granted" && e.action !== "withdrawn") throw new HttpError(400, "Action must be granted or withdrawn.");
      if (!wording) throw new HttpError(400, "Include the exact wording shown.");
      const normalised = wording.replace(/\s+/g, " ").trim();
      const version = str(e.notice_version, 200) ?? `sha256:${(await sha256Hex(normalised)).slice(0, 12)}`;
      rows.push({
        subject_id: user.id, // from JWT, never from body
        purpose,
        action: e.action,
        notice_version: version,
        wording,
        channel,
        source_url: cleanUrl(e.source_url),
        ip_hash: ipHash,
        user_agent: ua,
        // s35: the id of the parent or guardian record. Only a UUID is accepted; verifying that the
        // person really is the competent person happens in your own flow, not here.
        competent_person_id:
          typeof e.competent_person_id === "string" && UUID_RE.test(e.competent_person_id) ? e.competent_person_id : null,
      });
    }

    const { error } = await admin.schema("privacy").from("consent_events").insert(rows);
    if (error) throw new Error("consent_insert_failed");
    return json(req, { recorded: rows.length }, 201, METHODS);
  } catch (err) {
    return errorResponse(req, err, METHODS);
  }
});

// unsubscribe: one-click marketing opt-out (s69(4), s11(3)(b), s11(2)(b)).
// Deno edge function. Engineering guidance, not legal advice.
//
// Every marketing message must give the recipient a way to stop it (s69(4)).
// Withdrawal must be as easy as giving consent: no login wall.
//
// Deploy without JWT verification, because the person is not signed in:
//   supabase functions deploy unsubscribe --no-verify-jwt
// The HMAC-signed token is the authorisation. Secret: UNSUBSCRIBE_SECRET.
//
// Endpoints:
//   GET  ?t=<token>   Validates the token and returns { valid, purposes }. Does NOT
//                     unsubscribe, because mail scanners prefetch links. Your app's
//                     /unsubscribe page calls this, shows a single "Unsubscribe"
//                     button, and POSTs.
//   POST ?t=<token>   Unsubscribes. Accepts RFC 8058 one-click bodies
//                     ("List-Unsubscribe=One-Click", form-encoded) sent by mail
//                     providers, and JSON or empty bodies from your page.
//
// Email headers to send with every marketing email:
//   List-Unsubscribe: <https://<project>.supabase.co/functions/v1/unsubscribe?t=TOKEN>, <mailto:privacy@example.co.za?subject=unsubscribe>
//   List-Unsubscribe-Post: List-Unsubscribe=One-Click
//
// Make tokens on your server with signUnsubscribeToken() from _shared/privacy-config.ts.
// Put only a subject id and purposes in the token, never an email address.
//
// After this runs, suppress the person in every tool that sends marketing
// (email platform, SMS, WhatsApp, dialler) promptly (DM-07). Check
// privacy.consent_current at send time.

import {
  MARKETING_PURPOSES,
  adminClient,
  clientIp,
  env,
  HttpError,
  sha256Hex,
  verifyUnsubscribeToken,
} from "../_shared/privacy-config.ts";

const WORDING = "Unsubscribe from marketing.";

function respond(body: unknown, status = 200): Response {
  // Mail providers and your own page may call from any origin. The token
  // carries the authority, so a permissive CORS header is acceptable here
  // and avoids breaking the one-click flow. No cookies or credentials are used.
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "content-type",
      "Referrer-Policy": "no-referrer",
    },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return respond(null, 204);
  try {
    const url = new URL(req.url);
    let token = url.searchParams.get("t") ?? "";
    const secret = env("UNSUBSCRIBE_SECRET");

    if (req.method === "GET") {
      const payload = token ? await verifyUnsubscribeToken(token, secret) : null;
      if (!payload) return respond({ valid: false }, 400);
      return respond({ valid: true, purposes: payload.p.length ? payload.p : MARKETING_PURPOSES });
    }

    if (req.method !== "POST") throw new HttpError(405, "Use GET or POST.");

    // Read the body once. One-click posts are form-encoded (RFC 8058).
    const contentType = req.headers.get("Content-Type") ?? "";
    let channel = "unsubscribe_link";
    try {
      if (contentType.includes("application/x-www-form-urlencoded") || contentType.includes("multipart/form-data")) {
        const form = await req.formData();
        if (form.get("List-Unsubscribe") === "One-Click") channel = "list_unsubscribe_one_click";
        const t = form.get("t");
        if (!token && typeof t === "string") token = t;
      } else if (contentType.includes("application/json")) {
        const body = (await req.json()) as { t?: unknown };
        if (!token && typeof body.t === "string") token = body.t;
      }
    } catch {
      // Empty or malformed body. The token in the query string is enough.
    }

    const payload = token ? await verifyUnsubscribeToken(token, secret) : null;
    if (!payload) return respond({ error: "This unsubscribe link is not valid. Contact us and we will remove you." }, 400);

    const purposes = payload.p.length ? payload.p.filter((p) => /^[a-z0-9_]{1,100}$/.test(p)) : MARKETING_PURPOSES;

    const salt = Deno.env.get("CONSENT_IP_SALT") ?? "";
    const ip = clientIp(req);
    const ipHash = ip && salt ? await sha256Hex(`${salt}:${ip}`) : null;
    const notice = `sha256:${(await sha256Hex(WORDING)).slice(0, 12)}`;

    const admin = adminClient();
    const { error } = await admin
      .schema("privacy")
      .from("consent_events")
      .insert(
        purposes.map((purpose) => ({
          subject_id: payload.s,
          purpose,
          action: "withdrawn",
          notice_version: notice,
          wording: WORDING,
          channel,
          ip_hash: ipHash,
          user_agent: req.headers.get("User-Agent")?.slice(0, 500) ?? null,
        })),
      );
    if (error) throw new Error("unsubscribe_insert_failed");

    // Repeat clicks simply add another withdrawn event. That is harmless.
    return respond({ unsubscribed: true, purposes });
  } catch (err) {
    if (err instanceof HttpError) return respond({ error: err.message }, err.status);
    console.error("unsubscribe error", err instanceof Error ? err.name : typeof err);
    return respond({ error: "Something went wrong. Contact us and we will remove you." }, 500);
  }
});
